        _eqs,
        mo.Html('<div class="callout"><p><b>Both technologies use the intermediate <i>q(i)</i>, with the same weight η.</b> '
                'That is how the monopolist earns a share of all output, whichever factor does the task. '
                'Drag θ to move the line between machine-capable and labor-only tasks.</p></div>'),
