    _map = alt.layer(_area, _edge, _arealab, _pt_layer).properties(
        width=470, height=235, title=alt.Title("Where does labor scarcity raise output?", subtitle="Shaded: D > 1/θ"))
    _bars_d = pd.DataFrame({"k": ["Direct  (1 − θ)", "Indirect via automation", "Net  d ln Y / d ln L"], "o": [0, 1, 2]})
    _bars = alt.Chart(_bars_d).transform_calculate(
        ind="-pt * (1 - pt) / ((1 - pt) * pe + 1 / pD)",
        v="datum.o == 0 ? (1 - pt) : (datum.o == 1 ? -pt * (1 - pt) / ((1 - pt) * pe + 1 / pD) : (1 - pt) - pt * (1 - pt) / ((1 - pt) * pe + 1 / pD))")
    _yb = alt.Y("k:N", title=None, sort=["Direct  (1 − θ)", "Indirect via automation", "Net  d ln Y / d ln L"],
                axis=alt.Axis(labelFontSize=13, labelLimit=260, domain=False, ticks=False))
    _xb = alt.X("v:Q", title="Effect of a 1% rise in L on Y (%)", scale=alt.Scale(domain=[-1, 1], clamp=True), axis=alt.Axis(values=[-1, -0.5, 0, 0.5, 1]))
    _bm = _bars.mark_bar(height=24, cornerRadiusEnd=4).encode(
        y=_yb, x=_xb, color=alt.Color("k:N", scale=alt.Scale(domain=["Direct  (1 − θ)", "Indirect via automation", "Net  d ln Y / d ln L"], range=[NAVY, GREEN, INK]), legend=None))
    _bt = _bars.mark_text(fontSize=13, fontWeight=600, color=INK2, dx=8, align="left").transform_calculate(
        xx="max(datum.v, 0)").encode(y=_yb, x=alt.X("xx:Q", scale=alt.Scale(domain=[-1, 1])), text=alt.Text("v:Q", format="+.2f"))
    _zero = alt.Chart(pd.DataFrame({"x": [0]})).mark_rule(color=INK, strokeWidth=1.2).encode(x="x:Q")
    _verdict = alt.Chart(pd.DataFrame({"a": [0]})).transform_calculate(
        net="(1 - pt) - pt * (1 - pt) / ((1 - pt) * pe + 1 / pD)",
        t="((1 - pt) - pt * (1 - pt) / ((1 - pt) * pe + 1 / pD)) < 0 ? 'Net < 0: aging (lower L) RAISES output' : 'Net > 0: aging lowers output'").mark_text(
        align="left", fontSize=14, fontWeight=700, color=INK).encode(x=alt.value(0), y=alt.value(-16), text="t:N")
    _barch = alt.layer(_zero, _bm, _bt, _verdict).properties(width=300, height=105)
    _chart = alt.vconcat(_map, _barch, spacing=34).add_params(_pt, _pd, _pe)
    _eq = mo.md(r"""
    $$\frac{d\ln Y}{d\ln L} = \underbrace{1-\theta}_{\text{direct}\;>\;0} \;-\; \underbrace{\frac{\theta(1-\theta)}{(1-\theta)\,\varepsilon_\Gamma + \dfrac{1}{D}}}_{\text{indirect, via automation}\;>\;0}, \qquad D = \ln\tfrac{K}{\theta} - \ln\tfrac{L}{1-\theta}$$
    """)
    _txt = mo.md(r"""
    - **Direct effect:** fewer workers means less output from manual tasks, so lower *L* lowers *Y*.
    - **Indirect effect:** lower *L* raises θ (step 6), and each extra automated task adds *D* to ln *Y*.
    - **Aging raises output when the indirect effect wins:** that requires **D > 1/θ**, a large capital–labor
      gap **and** substantial automation already in place.
    """)
    _note = mo.Html('<div class="callout navy"><p><b>Condition (4) is not enough.</b> (4) only says D > 0, so automating raises output. '
                    'For aging to raise output, the gap must be larger still: D > 1/θ. At the illustration from the last two slides '
                    '(the dot), aging lowers output.</p></div>')
    slide(
        head("Theory", "Direct vs. indirect effect of a smaller workforce", step="7 / 7"),
        _eq,
        cols(mo.vstack([_txt, _note], gap=0.4), _chart, widths=(1, 0.95), gap=1.6),
        gap=0.2,
    )
    return


